// Prepare structured context for Classification Agent
const data = $input.first().json;

const context = {
  alarm_id:        data.alarm_id,
  incident_id:     data.incident_id,
  device_name:     data.device_name,
  alarm_type:      data.alarm_type,
  reported_severity: data.severity,
  interface_name:  data.interface_name || 'N/A',
  description:     data.description,
  alarm_timestamp: data.alarm_timestamp,
  agent_started_at: new Date().toISOString(),
};

return [{ json: { context, input: data } }];

// Parse and validate LLM output
const raw         = $input.first().json;
const agentOutput = typeof raw.text === 'string' ? raw.text : (typeof raw.content === 'string' ? raw.content : '');
// chainLlm runs with onError=continue, so a failed LLM call arrives here as { error }
const llmError    = raw.error ? (typeof raw.error === 'string' ? raw.error : JSON.stringify(raw.error)) : null;
const context     = $('Prepare Classification Context').first().json.context;

let parsed;
try {
  if (llmError) throw new Error('LLM call failed: ' + llmError);
  // Strip markdown fences if present
  const cleaned = agentOutput.replace(/```json?\n?/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  // Fallback classification if JSON parse fails
  parsed = {
    alarm_category:           'Unknown',
    severity:                 context.reported_severity,
    alarm_subtype:            context.alarm_type,
    is_service_affecting:     context.reported_severity === 'Critical' || context.reported_severity === 'Major',
    urgency:                  context.reported_severity === 'Critical' ? 'Immediate' : 'Medium',
    estimated_impact_scope:   'Single Device',
    classification_confidence: 0.3,
    classification_rationale:  'Fallback classification — LLM output could not be parsed.',
    tags:                     [context.alarm_type],
    parse_error:              e.message,
  };
}

// Validate required fields
const validCategories = ['Physical Layer','Data Link Layer','Network Layer','Service Layer','Environmental','Unknown'];
const validSeverities  = ['Critical','Major','Minor','Warning','Info'];
const validUrgencies   = ['Immediate','High','Medium','Low'];

if (!validCategories.includes(parsed.alarm_category)) parsed.alarm_category = 'Unknown';
if (!validSeverities.includes(parsed.severity))       parsed.severity = context.reported_severity;
if (!validUrgencies.includes(parsed.urgency))         parsed.urgency = 'Medium';

return [{
  json: {
    ...parsed,
    alarm_id:    context.alarm_id,
    incident_id: context.incident_id,
    agent_name:  'alarm_classification',
    completed_at: new Date().toISOString(),
  }
}];

// Return classification result to orchestrator
const result = $('Parse & Validate Output').first().json;
return [{ json: result }];
